function tinympc14_data_manifest(kind, builder)
% Record generated bytes and the active model sources, including shared Tool.
root = fileparts(fileparts(mfilename('fullpath')));
files = [{['build/staging/' kind '.h'], ['build/staging/' kind '.c']}, tinympc14_manifest_sources()];
assert(any(strcmp(files, builder)), 'Builder missing from manifest sources: %s', builder);
fid = fopen(fullfile(root, 'build', [kind '.sha256']), 'w');
assert(fid >= 0, 'Cannot write model manifest');
cleanup = onCleanup(@() fclose(fid)); %#ok<NASGU>
fprintf(fid, '# leg4-manifest v3\n');
for k = 1:numel(files)
    fprintf(fid, '%s *%s\n', tinympc14_sha256(fullfile(root, files{k})), files{k});
end
end
